// Package repository is the region module's database access layer.
//
// The regiondb package generated by sqlc stays INSIDE this package: only the
// [models] domain types are handed out, and pgtype appears in no signature.
// The boundary is deliberate — the service and API layers do not bind to a
// storage detail, and when the generated code is regenerated only this package
// is affected.
//
// Raw errors do not cross the boundary either: pgx.ErrNoRows and PostgreSQL
// constraint violations are converted here into the typed errors of
// core/errors, so the HTTP layer picks the right status code (plan Section
// 2.7).
//
// # Lock order
//
// Every flow that touches region and country rows together takes the locks IN
// THE SAME ORDER: FIRST the region, THEN the country. Because there is a single
// order, two flows cannot lock in a way that has each wait for the other
// (deadlock). A single query that breaks the order is enough to undo this,
// which is why the queries that take locks are documented separately under
// queries/.
package repository

import (
	"context"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/bdrtr/gobit/core/errors"
	"github.com/bdrtr/gobit/internal/modules/region/models"
	"github.com/bdrtr/gobit/internal/modules/region/repository/regiondb"
)

// Error codes; the calling side can look at these with errors.CodeOf.
const (
	// CodeRegionNotFound reports that the requested region was not found.
	CodeRegionNotFound = "region_not_found"
	// CodeCountryNotFound reports that the requested country was not found.
	CodeCountryNotFound = "country_not_found"
	// CodeCurrencyNotFound reports that the requested currency was not found.
	CodeCurrencyNotFound = "currency_not_found"
	// CodeUnknownCurrency reports that a region was given an undefined currency.
	CodeUnknownCurrency = "region_unknown_currency"
	// CodeCountryTaken reports that the country belongs to another region.
	CodeCountryTaken = "country_already_in_region"
	// CodeCountryNotInRegion reports that the country does not belong to that region.
	CodeCountryNotInRegion = "country_not_in_region"
	// CodeConstraintViolation reports that a database constraint was violated.
	CodeConstraintViolation = "region_constraint_violation"
	// CodeDuplicate reports a uniqueness violation.
	CodeDuplicate = "region_duplicate"
	// CodeQueryFailed reports an unexpected database error.
	CodeQueryFailed = "region_query_failed"
	// CodeCanceled reports a context cancellation.
	CodeCanceled = "region_canceled"
	// CodeTxFailed reports a failure in transaction management.
	CodeTxFailed = "region_tx_failed"
)

// PostgreSQL SQLSTATE codes (the ones that are needed).
const (
	sqlstateCheckViolation       = "23514"
	sqlstateUniqueViolation      = "23505"
	sqlstateForeignKeyViolation  = "23503"
	sqlstateNotNullViolation     = "23502"
	sqlstateStringDataRightTrunc = "22001"
)

// constraintRegionCurrency is the migration's name for the foreign key that
// binds a region to its currency. It is used to turn the driver error into a
// meaningful message; the name has to match the migration exactly.
const constraintRegionCurrency = "region_currency_fk"

// Repo provides access to the region tables. It is safe for concurrent use.
type Repo struct {
	pool *pgxpool.Pool
	q    *regiondb.Queries
}

// New builds a repository that runs over the given pool.
//
// A nil pool is reported as a typed error on the first call, not at
// construction; the construction path does not panic.
func New(pool *pgxpool.Pool) *Repo {
	r := &Repo{pool: pool}
	if pool != nil {
		r.q = regiondb.New(pool)
	}
	return r
}

// ready verifies that the pool is usable.
func (r *Repo) ready() error {
	if r == nil || r.pool == nil || r.q == nil {
		return errors.Unavailable(CodeQueryFailed, "region database pool is not set up")
	}
	return nil
}

// inTx runs fn in a single transaction; if fn returns an error the
// transaction is ROLLED BACK.
//
// It is mandatory for flows that take locks: a FOR UPDATE / FOR SHARE lock is
// released when the transaction ends, so a lock without a transaction would
// protect nothing.
func (r *Repo) inTx(ctx context.Context, fn func(q *regiondb.Queries) error) error {
	if err := r.ready(); err != nil {
		return err
	}

	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return wrapDB(err, "the transaction could not be begun")
	}
	// Rollback called after Commit returns pgx.ErrTxClosed, which is ignored;
	// this lets the defer stay safely in place on the successful path too.
	defer func() { _ = tx.Rollback(ctx) }()

	if err := fn(r.q.WithTx(tx)); err != nil {
		return err
	}

	if err := tx.Commit(ctx); err != nil {
		return wrapDB(err, "the transaction could not be committed")
	}
	return nil
}

// wrapDB converts a raw database error into a typed error.
//
// The classification is deliberate: a constraint violation is a CLIENT error
// (422), a uniqueness violation is a conflict (409), a cancellation is
// temporary unavailability (503); everything else is a server error and its
// message IS NOT LEAKED to the client (see core/http).
//
// The region's currency foreign key is handled on its own: "unknown currency"
// is an input error the client can correct, and its message has to say what to
// do rather than name the constraint.
func wrapDB(err error, format string, a ...any) error {
	if err == nil {
		return nil
	}
	switch {
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		return errors.Wrap(err, errors.KindUnavailable, CodeCanceled, format, a...)
	case errors.Is(err, pgx.ErrTxClosed), errors.Is(err, pgx.ErrTxCommitRollback):
		return errors.Wrap(err, errors.KindInternal, CodeTxFailed, format, a...)
	}

	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		if pgErr.Code == sqlstateForeignKeyViolation && pgErr.ConstraintName == constraintRegionCurrency {
			return errors.Wrap(err, errors.KindInvalid, CodeUnknownCurrency,
				"%s: the currency is not defined", sprintf(format, a...))
		}
		switch pgErr.Code {
		case sqlstateUniqueViolation:
			return errors.Wrap(err, errors.KindConflict, CodeDuplicate,
				"%s (constraint: %s)", sprintf(format, a...), pgErr.ConstraintName)
		case sqlstateCheckViolation, sqlstateForeignKeyViolation,
			sqlstateNotNullViolation, sqlstateStringDataRightTrunc:
			return errors.Wrap(err, errors.KindInvalid, CodeConstraintViolation,
				"%s (constraint: %s)", sprintf(format, a...), pgErr.ConstraintName)
		}
	}

	return errors.Wrap(err, errors.KindInternal, CodeQueryFailed, format, a...)
}

// notFoundOr converts pgx.ErrNoRows into NotFound and everything else through wrapDB.
func notFoundOr(err error, code, format string, a ...any) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, pgx.ErrNoRows) {
		return errors.NotFound(code, format, a...)
	}
	return wrapDB(err, format, a...)
}

// sprintf formats the error message once.
//
// On calls without arguments the format is returned UNCHANGED; otherwise a
// percent sign in the message (e.g. "%!d(MISSING)") would reach the user as
// corrupted text.
func sprintf(format string, a ...any) string {
	if len(a) == 0 {
		return format
	}
	return fmt.Sprintf(format, a...)
}

// toTime converts a non-NULL timestamp into a UTC time.Time.
//
// An invalid (NULL) timestamp returns the zero time: on NOT NULL columns this
// cannot happen, and if it does, the zero time is a value that does not panic
// and stands out in a test.
func toTime(ts pgtype.Timestamptz) time.Time {
	if !ts.Valid {
		return time.Time{}
	}
	return ts.Time.UTC()
}

// toTimePtr converts a nullable timestamp into a *time.Time.
func toTimePtr(ts pgtype.Timestamptz) *time.Time {
	if !ts.Valid {
		return nil
	}
	t := ts.Time.UTC()
	return &t
}

// fromTime converts a time into a NOT NULL timestamp; it is always written in UTC.
func fromTime(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t.UTC(), Valid: true}
}

// toRegion converts the generated row into the domain model.
func toRegion(row regiondb.Region) models.Region {
	return models.Region{
		ID:             row.ID,
		Name:           row.Name,
		CurrencyCode:   row.CurrencyCode,
		AutomaticTaxes: row.AutomaticTaxes,
		TaxRate:        row.TaxRate,
		CreatedAt:      toTime(row.CreatedAt),
		UpdatedAt:      toTime(row.UpdatedAt),
		DeletedAt:      toTimePtr(row.DeletedAt),
	}
}

// toCountry converts the generated row into the domain model.
//
// The RegionID pointer is COPIED: carrying the generated row's pointer over
// as-is would mean that a caller changing the model also changes the row.
func toCountry(row regiondb.Country) models.Country {
	country := models.Country{
		Code:      row.Iso2,
		Name:      row.Name,
		CreatedAt: toTime(row.CreatedAt),
		UpdatedAt: toTime(row.UpdatedAt),
	}
	if row.RegionID != nil {
		id := *row.RegionID
		country.RegionID = &id
	}
	return country
}

// toCurrency converts the generated row into the domain model.
func toCurrency(row regiondb.Currency) models.Currency {
	return models.Currency{
		Code:          row.Code,
		Symbol:        row.Symbol,
		Name:          row.Name,
		DecimalDigits: row.DecimalDigits,
		CreatedAt:     toTime(row.CreatedAt),
		UpdatedAt:     toTime(row.UpdatedAt),
	}
}
